Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'data/gallery', 'data/gallery/2026', 'data/other', 'spare/gallery' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'up.txt'), "uploaded`n")
[IO.File]::WriteAllText((Join-Path $PWD 'data/gallery/sunset.txt'), "sunset`n")
