cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'data', '--bucket', 'pics=/gallery', '--allow-uploads', '--list-directories', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', 's3://127.0.0.1:8080/', 'https://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret s3://pics/sunset.txt } finally { Stop-Process $server0 }
